//! 📨️ Fixed canonical mesh messages bind every bounded source page to the same patch and native resource.
use super::*;
use ui_scene::math::{MESH3D_OWNER_BYTE_CAPACITY,MESH3D_RESOURCE_COMPONENT_COUNT_CAPACITY};
pub const UI_NATIVE_MESH_MESSAGE_WORDS:usize=46;
pub const UI_NATIVE_MESH_MESSAGE_BYTES:usize=UI_NATIVE_MESH_MESSAGE_WORDS*8;
const MAGIC:u64=0x314853454d4f494d;
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub struct UiNativeMeshPatchIdentity{pub activation_generation:u64,pub instance_id:u32,pub guest_lifetime:u64,pub patch_sequence:u64,pub revision:u64}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub struct UiNativeMeshMessageBinding{pub patch:UiNativeMeshPatchIdentity,pub resource_ordinal:usize,pub source:Mesh3dResourceIdentity}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub enum UiNativeMeshMessageContent{Descriptor{descriptor:UiNativeMeshDescriptor,surface_bytes:usize,mesh_key_bytes:usize},Window{channel:UiNativeMeshChannel,offset:usize,total_bytes:usize,bytes:[u8;64],length:usize},ResourceComplete,SourceReturned{resource_count:usize}}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub struct UiNativeMeshMessage{pub binding:UiNativeMeshMessageBinding,pub sequence:u64,pub content:UiNativeMeshMessageContent}
impl UiNativeMeshMessageBinding{
 fn validate(self)->Result<(),Mesh3dFault>{let patch=self.patch;let source=self.source;if patch.activation_generation==0||patch.guest_lifetime==0||patch.patch_sequence==0||patch.revision==0||source.operation==0||source.generation==0||source.cache_epoch==0||self.resource_ordinal>=UI_NATIVE_RESOURCE_CAPACITY{return Err(Mesh3dFault::Schema)}Ok(())}
}
impl UiNativeMeshMessage{
 pub fn canonical_words(self)->Result<[u64;UI_NATIVE_MESH_MESSAGE_WORDS],Mesh3dFault>{self.binding.validate()?;if self.sequence==0{return Err(Mesh3dFault::Schema)}let mut words=[0;UI_NATIVE_MESH_MESSAGE_WORDS];let binding=self.binding;let patch=binding.patch;let source=binding.source;words[..14].copy_from_slice(&[MAGIC,0,patch.activation_generation,u64::from(patch.instance_id),patch.guest_lifetime,patch.patch_sequence,patch.revision,binding.resource_ordinal as u64,source.operation,source.generation,source.revision,source.cache_epoch,source.source_slot as u64,self.sequence]);match self.content{
  UiNativeMeshMessageContent::Descriptor{descriptor,surface_bytes,mesh_key_bytes}=>{if descriptor.identity!=source||descriptor.geometry_bytes>MESH3D_OWNER_BYTE_CAPACITY||descriptor.component_counts.iter().any(|count|*count>MESH3D_RESOURCE_COMPONENT_COUNT_CAPACITY)||surface_bytes>ui_contract::UI_TEXT_MAX_BYTES||mesh_key_bytes>ui_contract::UI_TEXT_MAX_BYTES{return Err(Mesh3dFault::Schema)}let schema=descriptor.schema;words[19..38].copy_from_slice(&[descriptor.geometry_bytes as u64,descriptor.component_counts[0]as u64,descriptor.component_counts[1]as u64,descriptor.component_counts[2]as u64,u64::from(schema.vertices),u64::from(schema.indices),u64::from(schema.face_ids),u64::from(schema.vertex_ids),u64::from(schema.edges),u64::from(schema.edge_ids),u64::from(schema.uvs),u64::from(schema.colors),u64::from(schema.surface_uvs[0]),u64::from(schema.surface_uvs[1]),u64::from(schema.surface_uvs[2]),u64::from(schema.surface_uvs[3]),u64::from(schema.tangents),surface_bytes as u64,mesh_key_bytes as u64]);},
  UiNativeMeshMessageContent::Window{channel,offset,total_bytes,bytes,length}=>{if length>64||offset.checked_add(length).is_none_or(|end|end>total_bytes)||total_bytes>MESH3D_OWNER_BYTE_CAPACITY||bytes[length..].iter().any(|byte|*byte!=0){return Err(Mesh3dFault::Schema)}words[1]=match channel{UiNativeMeshChannel::Geometry=>1,UiNativeMeshChannel::ComponentLabel{domain,group}=>{if domain>=3||group>=MESH3D_RESOURCE_COMPONENT_COUNT_CAPACITY{return Err(Mesh3dFault::Schema)}words[17]=domain as u64;words[18]=group as u64;2},UiNativeMeshChannel::Surface=>3,UiNativeMeshChannel::MeshKey=>4};words[14]=length as u64;words[15]=offset as u64;words[16]=total_bytes as u64;for(index,window)in bytes.chunks_exact(8).enumerate(){words[38+index]=u64::from_le_bytes(window.try_into().unwrap());}},
  UiNativeMeshMessageContent::ResourceComplete=>words[1]=5,
  UiNativeMeshMessageContent::SourceReturned{resource_count}=>{if resource_count>UI_NATIVE_RESOURCE_CAPACITY{return Err(Mesh3dFault::Schema)}words[1]=6;words[16]=resource_count as u64;}
 }Ok(words)}
 pub fn from_canonical_words(words:[u64;UI_NATIVE_MESH_MESSAGE_WORDS])->Result<Self,Mesh3dFault>{let extent=|index:usize|usize::try_from(words[index]).map_err(|_|Mesh3dFault::Schema);let count=|index:usize|u32::try_from(words[index]).map_err(|_|Mesh3dFault::Schema);if words[0]!=MAGIC{return Err(Mesh3dFault::Schema)}let binding=UiNativeMeshMessageBinding{patch:UiNativeMeshPatchIdentity{activation_generation:words[2],instance_id:count(3)?,guest_lifetime:words[4],patch_sequence:words[5],revision:words[6]},resource_ordinal:extent(7)?,source:Mesh3dResourceIdentity{operation:words[8],generation:words[9],revision:words[10],cache_epoch:words[11],source_slot:extent(12)?}};let content=match words[1]{
  0=>UiNativeMeshMessageContent::Descriptor{descriptor:UiNativeMeshDescriptor{identity:binding.source,geometry_bytes:extent(19)?,component_counts:[extent(20)?,extent(21)?,extent(22)?],schema:Mesh3dSchema{vertices:count(23)?,indices:count(24)?,face_ids:count(25)?,vertex_ids:count(26)?,edges:count(27)?,edge_ids:count(28)?,uvs:count(29)?,colors:count(30)?,surface_uvs:[count(31)?,count(32)?,count(33)?,count(34)?],tangents:count(35)?}},surface_bytes:extent(36)?,mesh_key_bytes:extent(37)?},
  1..=4=>{let channel=match words[1]{1=>UiNativeMeshChannel::Geometry,2=>UiNativeMeshChannel::ComponentLabel{domain:extent(17)?,group:extent(18)?},3=>UiNativeMeshChannel::Surface,_=>UiNativeMeshChannel::MeshKey};let mut bytes=[0;64];for(index,word)in words[38..].iter().enumerate(){bytes[index*8..index*8+8].copy_from_slice(&word.to_le_bytes());}UiNativeMeshMessageContent::Window{channel,offset:extent(15)?,total_bytes:extent(16)?,bytes,length:extent(14)?}},
  5=>UiNativeMeshMessageContent::ResourceComplete,6=>UiNativeMeshMessageContent::SourceReturned{resource_count:extent(16)?},_=>return Err(Mesh3dFault::Schema)
 };let result=Self{binding,sequence:words[13],content};if result.canonical_words()?!=words{return Err(Mesh3dFault::Schema)}Ok(result)}
 pub fn is_mesh_message(source:&[u8])->bool{source.len()>=8&&source[..8]==MAGIC.to_le_bytes()}
}
#[derive(Debug)]
pub struct UiNativeMeshMessageReceiving{words:[u64;UI_NATIVE_MESH_MESSAGE_WORDS],offset:usize,complete:bool}
impl Default for UiNativeMeshMessageReceiving{fn default()->Self{Self{words:[0;UI_NATIVE_MESH_MESSAGE_WORDS],offset:0,complete:false}}}
impl UiNativeMeshMessageReceiving{
 pub fn offset(&self)->usize{self.offset}
 pub fn receive_step(&mut self,source:&[u8],grant:RetainedCloneGrant)->Result<(Option<UiNativeMeshMessage>,RetainedCloneProgress),Mesh3dFault>{if self.complete||source.len()!=UI_NATIVE_MESH_MESSAGE_BYTES{return Err(Mesh3dFault::Order)}if grant.maximum_items==0||grant.maximum_depth==0{return Ok((None,Default::default()))}if self.offset==source.len(){let message=UiNativeMeshMessage::from_canonical_words(self.words)?;self.complete=true;return Ok((Some(message),RetainedCloneProgress{copied_items:1,..Default::default()}))}let count=(source.len()-self.offset).min(64);if grant.maximum_copy_bytes<count{return Ok((None,Default::default()))}for(index,word)in source[self.offset..self.offset+count].chunks_exact(8).enumerate(){self.words[self.offset/8+index]=u64::from_le_bytes(word.try_into().unwrap());}self.offset+=count;Ok((None,RetainedCloneProgress{copied_items:1,copied_bytes:count,..Default::default()}))}
}

#[derive(Debug)]
pub struct UiNativeMeshMessageWriting{words:[u64;UI_NATIVE_MESH_MESSAGE_WORDS],offset:usize}
impl UiNativeMeshMessageWriting{
 pub fn admit(source:UiNativeMeshMessage,grant:RetainedCloneGrant)->Result<Option<(Self,RetainedCloneProgress)>,Mesh3dFault>{if grant.maximum_items==0||grant.maximum_depth==0{return Ok(None)}Ok(Some((Self{words:source.canonical_words()?,offset:0},RetainedCloneProgress{copied_items:1,..Default::default()})))}
 pub fn offset(&self)->usize{self.offset}
 pub fn copy_window_step(&mut self,output:&mut[u8;64],grant:RetainedCloneGrant)->(usize,RetainedCloneProgress){let length=(UI_NATIVE_MESH_MESSAGE_BYTES-self.offset).min(64);if length==0||grant.maximum_items==0||grant.maximum_depth==0||grant.maximum_copy_bytes<length{return(0,Default::default())}for(index,word)in self.words[self.offset/8..(self.offset+length)/8].iter().enumerate(){output[index*8..index*8+8].copy_from_slice(&word.to_le_bytes());}self.offset+=length;(length,RetainedCloneProgress{copied_items:1,copied_bytes:length,..Default::default()})}
 pub fn complete(&self)->bool{self.offset==UI_NATIVE_MESH_MESSAGE_BYTES}
}
impl UiNativeResourceLoans{
 pub fn describe_mesh_message_on_original(&mut self,binding:UiNativeMeshMessageBinding,sequence:u64,cx:&mut semio_framework_job::StepContext<'_>)->Result<Option<UiNativeMeshMessage>,semio_framework_job::OriginalTurnFailure>{
  if binding.validate().is_err()||sequence==0{return Err(semio_framework_value::ValueError::literal(semio_framework_value::ValueRefusalKind::InvariantViolated,"original native descriptor message has no exact patch binding").into())}
  let Some(descriptor)=self.describe_mesh_on_original(binding.resource_ordinal,cx)?else{return Ok(None)};
  if descriptor.identity!=binding.source{return Err(semio_framework_value::ValueError::literal(semio_framework_value::ValueRefusalKind::InvariantViolated,"original native descriptor message substituted resource identity").into())}
  let row=self.row(binding.resource_ordinal).unwrap();Ok(Some(UiNativeMeshMessage{binding,sequence,content:UiNativeMeshMessageContent::Descriptor{descriptor,surface_bytes:row.surface.as_str().len(),mesh_key_bytes:row.mesh_key.as_str().len()}}))
 }
 pub fn read_mesh_message_window_on_original(&mut self,binding:UiNativeMeshMessageBinding,sequence:u64,descriptor:UiNativeMeshDescriptor,channel:UiNativeMeshChannel,offset:usize,cx:&mut semio_framework_job::StepContext<'_>)->Result<Option<UiNativeMeshMessage>,semio_framework_job::OriginalTurnFailure>{
  if binding.validate().is_err()||sequence==0||descriptor.identity!=binding.source{return Err(semio_framework_value::ValueError::literal(semio_framework_value::ValueRefusalKind::InvariantViolated,"original native page message substituted its exact patch/resource binding").into())}
  let mut bytes=[0;64];let Some(chunk)=self.read_mesh_chunk_on_original(binding.resource_ordinal,descriptor,channel,offset,&mut bytes,cx)?else{return Ok(None)};
  Ok(Some(UiNativeMeshMessage{binding,sequence,content:UiNativeMeshMessageContent::Window{channel,offset,total_bytes:chunk.total_bytes,bytes,length:chunk.bytes}}))
 }
}

/// 📥️ One retained resource receiver keeps each whole packet until its actual destination frontier accepts it.
pub struct UiNativeMeshReceiving{source:Option<semio_framework_job::OriginalCallerSourceLoan>,recipient:usize,binding:UiNativeMeshMessageBinding,descriptor:UiNativeMeshDescriptor,next_sequence:u64,packet:Option<UiNativeMeshMessage>,packet_offset:usize,names:[[u8;ui_contract::UI_TEXT_MAX_BYTES];2],name_extents:[usize;2],name_offsets:[usize;2],surface:Option<ui_contract::UiText>,mesh_key:Option<ui_contract::UiText>,receiver:Option<ui_scene::math::Mesh3dResourceReceiving>,ready:Option<UiNativeMeshResource>,closing:bool,complete:bool}
impl UiNativeMeshReceiving{
 pub fn admit(message:UiNativeMeshMessage,cx:&mut semio_framework_job::StepContext<'_>)->Result<Option<Self>,semio_framework_job::OriginalTurnFailure>{message.canonical_words().map_err(mesh_receiving_fault)?;let UiNativeMeshMessageContent::Descriptor{descriptor,surface_bytes,mesh_key_bytes}=message.content else{return Err(mesh_receiving_fault(Mesh3dFault::Order))};if surface_bytes==0||mesh_key_bytes==0||message.binding.source.operation!=cx.operation().0||message.binding.source.generation!=cx.generation().0{return Err(mesh_receiving_fault(Mesh3dFault::Schema))}cx.original_source_parent()?;if cx.should_yield()||cx.is_cancelled(){return Ok(None)}descriptor.schema.validate().map_err(mesh_receiving_fault)?;let parent=cx.original_source_parent()?;let Some(source)=parent.admit_loan(cx)?else{return Ok(None)};Ok(Some(Self{source:Some(source),recipient:cx.original_recipient_identity(),binding:message.binding,descriptor,next_sequence:message.sequence,packet:None,packet_offset:0,names:[[0;ui_contract::UI_TEXT_MAX_BYTES];2],name_extents:[surface_bytes,mesh_key_bytes],name_offsets:[0;2],surface:None,mesh_key:None,receiver:None,ready:None,closing:false,complete:false}))}
 pub fn binding(&self)->UiNativeMeshMessageBinding{self.binding}
 pub fn destination(&self)->Option<&UiNativeMeshResource>{self.ready.as_ref()}
 pub fn destination_mut(&mut self)->Option<&mut UiNativeMeshResource>{self.ready.as_mut()}
 pub fn destination_donor(&mut self)->&mut Option<UiNativeMeshResource>{&mut self.ready}
 pub fn is_complete(&self)->bool{self.complete&&!self.closing}
 pub fn receive_step(&mut self,donor:&mut Option<UiNativeMeshMessage>,cx:&mut semio_framework_job::StepContext<'_>)->Result<bool,semio_framework_job::OriginalTurnFailure>{
  self.validate_source(cx,false)?;if self.closing||self.complete||self.binding.source.operation!=cx.operation().0||self.binding.source.generation!=cx.generation().0{return Err(mesh_receiving_fault(Mesh3dFault::Order))}let message=donor.as_ref().copied().ok_or_else(||mesh_receiving_fault(Mesh3dFault::Order))?;if message.sequence==u64::MAX||message.binding!=self.binding||message.sequence!=self.next_sequence||self.packet.is_some_and(|held|held!=message){return Err(mesh_receiving_fault(Mesh3dFault::Stale))}if cx.should_yield()||cx.is_cancelled(){return Ok(false)}let grant=cx.retained_grant();if grant.maximum_items==0||grant.maximum_depth==0{return Ok(false)}
  if self.receiver.is_none(){let Some((receiver,progress))=ui_scene::math::Mesh3dResourceReceiving::admit(self.descriptor.identity,self.descriptor.schema,self.descriptor.component_counts,self.descriptor.geometry_bytes,grant).map_err(mesh_receiving_fault)?else{return Ok(false)};self.receiver=Some(receiver);cx.consume_fuel(1);cx.consume_retained(progress)?;return Ok(false)}
  if self.packet.is_none(){self.packet=Some(message);cx.consume_fuel(1);cx.consume_retained(RetainedCloneProgress{copied_items:1,..Default::default()})?;return Ok(false)}
  if !matches!(message.content,UiNativeMeshMessageContent::Descriptor{..}){let progress=self.receiver.as_mut().ok_or_else(||mesh_receiving_fault(Mesh3dFault::Order))?.advance(grant).map_err(mesh_receiving_fault)?;if progress!=Default::default(){cx.consume_fuel(1);cx.consume_retained(progress)?;return Ok(false)}}
  match message.content{
   UiNativeMeshMessageContent::Descriptor{descriptor,surface_bytes,mesh_key_bytes}=>{if descriptor!=self.descriptor||[surface_bytes,mesh_key_bytes]!=self.name_extents{return Err(mesh_receiving_fault(Mesh3dFault::Schema))}},
   UiNativeMeshMessageContent::Window{channel,offset,total_bytes,bytes,length}=>{
    if self.packet_offset<length{let current=offset.checked_add(self.packet_offset).ok_or_else(||mesh_receiving_fault(Mesh3dFault::Schema))?;let body=&bytes[self.packet_offset..length];let step=match channel{
     UiNativeMeshChannel::Surface|UiNativeMeshChannel::MeshKey=>{let index=usize::from(channel==UiNativeMeshChannel::MeshKey);if total_bytes!=self.name_extents[index]||current!=self.name_offsets[index]||current+body.len()>self.name_extents[index]{return Err(mesh_receiving_fault(Mesh3dFault::Order))}let count=body.len().min(grant.maximum_copy_bytes);if count==0{return Ok(false)}self.names[index][current..current+count].copy_from_slice(&body[..count]);self.name_offsets[index]+=count;ui_scene::math::Mesh3dReceivingStep{consumed_bytes:count,progress:RetainedCloneProgress{copied_items:1,copied_bytes:count,..Default::default()}}},
     UiNativeMeshChannel::Geometry=>{if total_bytes!=self.descriptor.geometry_bytes{return Err(mesh_receiving_fault(Mesh3dFault::Schema))}self.receiver.as_mut().unwrap().receive_geometry(current,body,grant).map_err(mesh_receiving_fault)?},
     UiNativeMeshChannel::ComponentLabel{domain,group}=>self.receiver.as_mut().unwrap().receive_label(domain,group,current,total_bytes,body,grant).map_err(mesh_receiving_fault)?,
    };if step.progress==Default::default(){return Ok(false)}self.packet_offset+=step.consumed_bytes;cx.consume_fuel(1);cx.consume_retained(step.progress)?;return Ok(false)}
    if channel==UiNativeMeshChannel::Geometry&&self.receiver.as_ref().unwrap().geometry_write_pending(){let offset=self.receiver.as_ref().unwrap().geometry_offset();let step=self.receiver.as_mut().unwrap().receive_geometry(offset,&[],grant).map_err(mesh_receiving_fault)?;if step.progress==Default::default(){return Ok(false)}cx.consume_fuel(1);cx.consume_retained(step.progress)?;return Ok(false)}
    if let UiNativeMeshChannel::Surface|UiNativeMeshChannel::MeshKey=channel{let index=usize::from(channel==UiNativeMeshChannel::MeshKey);if self.name_offsets[index]==self.name_extents[index]&&if index==0{self.surface.is_none()}else{self.mesh_key.is_none()}{let extent=self.name_extents[index];if grant.maximum_copy_bytes<extent{return Ok(false)}let text=std::str::from_utf8(&self.names[index][..extent]).map_err(|_|mesh_receiving_fault(Mesh3dFault::Schema))?;let text=ui_contract::UiText::try_from_str(text).ok_or_else(||mesh_receiving_fault(Mesh3dFault::Schema))?;if index==0{self.surface=Some(text)}else{self.mesh_key=Some(text)}cx.consume_fuel(1);cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:extent,..Default::default()})?;return Ok(false)}}
    if let UiNativeMeshChannel::ComponentLabel{domain,group}=channel{if offset+length==total_bytes&&self.receiver.as_ref().unwrap().label_frontier()==Some((domain,group,total_bytes)){let step=self.receiver.as_mut().unwrap().receive_label(domain,group,total_bytes,total_bytes,&[],grant).map_err(mesh_receiving_fault)?;if step.progress==Default::default(){return Ok(false)}cx.consume_fuel(1);cx.consume_retained(step.progress)?;return Ok(false)}}
   },
   UiNativeMeshMessageContent::ResourceComplete=>{if self.surface.is_none()||self.mesh_key.is_none(){return Err(mesh_receiving_fault(Mesh3dFault::Incomplete))}if self.ready.is_none(){let Some((owner,progress))=self.receiver.as_mut().unwrap().take_ready(grant)else{return Ok(false)};self.ready=Some(UiNativeMeshResource{surface:self.surface.take().unwrap(),mesh_key:self.mesh_key.take().unwrap(),owner});cx.consume_fuel(1);cx.consume_retained(progress)?;return Ok(false)}self.complete=true;},
   UiNativeMeshMessageContent::SourceReturned{..}=>return Err(mesh_receiving_fault(Mesh3dFault::Order)),
  }
  cx.consume_fuel(1);cx.consume_retained(RetainedCloneProgress{copied_items:1,..Default::default()})?;self.packet=None;self.packet_offset=0;self.next_sequence=self.next_sequence.checked_add(1).ok_or_else(||mesh_receiving_fault(Mesh3dFault::Order))?;donor.take();Ok(true)
 }
 fn validate_source(&self,cx:&semio_framework_job::StepContext<'_>,retirement:bool)->Result<(),semio_framework_job::OriginalTurnFailure>{if self.recipient!=cx.original_recipient_identity(){return Err(mesh_receiving_fault(Mesh3dFault::Stale))}let source=self.source.as_ref().ok_or_else(||mesh_receiving_fault(Mesh3dFault::Closing))?;if retirement{source.validate_retirement_context(cx)}else{source.validate_context(cx)}}
 pub fn source_is_returned(&self)->bool{self.source.is_none()&&self.receiver.is_none()&&self.packet.is_none()}
 pub fn return_source_step(&mut self,cx:&mut semio_framework_job::StepContext<'_>)->Result<bool,semio_framework_job::OriginalTurnFailure>{if !self.complete||self.packet.is_some(){return Err(mesh_receiving_fault(Mesh3dFault::Incomplete))}if self.source_is_returned(){return Ok(true)}self.validate_source(cx,true)?;cx.with_original_retirement(|cx|{if cx.retirement_should_yield(){return Ok(false)}let grant=cx.retained_grant();if grant.maximum_items==0||grant.maximum_depth==0{return Ok(false)}if let Some(receiver)=self.receiver.as_ref(){if !receiver.terminal_is_empty(){return Err(mesh_receiving_fault(Mesh3dFault::Incomplete))}self.receiver.take();cx.consume_fuel(1);cx.consume_retained(RetainedCloneProgress{copied_items:1,..Default::default()})?;return Ok(false)}let parent=cx.original_source_parent()?;self.source.as_mut().unwrap().close_step(parent,cx)?;if self.source.as_ref().unwrap().terminal_is_empty(){self.source.take();}Ok(self.source_is_returned())})}
 pub fn close_step(&mut self,cx:&mut semio_framework_job::StepContext<'_>)->Result<bool,semio_framework_job::OriginalTurnFailure>{if self.terminal_is_empty(){return Ok(true)}if self.source.is_some(){self.validate_source(cx,true)?;}else if self.recipient!=cx.original_recipient_identity(){return Err(mesh_receiving_fault(Mesh3dFault::Stale))}if self.binding.source.operation!=cx.operation().0||self.binding.source.generation!=cx.generation().0{return Err(mesh_receiving_fault(Mesh3dFault::Stale))}self.closing=true;cx.with_original_retirement(|cx|{if cx.retirement_should_yield(){return Ok(false)}let grant=cx.retained_grant();if grant.maximum_items==0||grant.maximum_depth==0{return Ok(false)}if let Some(destination)=self.ready.as_mut(){let demand=destination.owner.close_demands(grant.maximum_copy_bytes).map_err(mesh_receiving_fault)?;if grant.maximum_copy_bytes<demand.copy_bytes||grant.maximum_capacity_bytes<demand.capacity_bytes||grant.maximum_release_bytes<demand.release_bytes||grant.maximum_depth<demand.depth{return Ok(false)}let step=destination.owner.close_step(grant).map_err(mesh_receiving_fault)?;cx.consume_fuel(1);cx.consume_retained(step.progress)?;if step.complete{self.ready.take();}return Ok(false)}if let Some(receiver)=self.receiver.as_mut(){if !receiver.terminal_is_empty(){let step=receiver.close_step(grant).map_err(mesh_receiving_fault)?;if step.progress!=Default::default(){cx.consume_fuel(1);cx.consume_retained(step.progress)?;}return Ok(false)}self.receiver.take();cx.consume_fuel(1);cx.consume_retained(RetainedCloneProgress{copied_items:1,..Default::default()})?;return Ok(false)}if self.packet.is_some()||self.surface.is_some()||self.mesh_key.is_some(){self.packet=None;self.surface=None;self.mesh_key=None;cx.consume_fuel(1);cx.consume_retained(RetainedCloneProgress{copied_items:1,..Default::default()})?;return Ok(false)}if let Some(source)=self.source.as_mut(){let parent=cx.original_source_parent()?;source.close_step(parent,cx)?;if source.terminal_is_empty(){self.source.take();}return Ok(false)}Ok(true)})}
 pub fn terminal_is_empty(&self)->bool{self.source.is_none()&&self.receiver.is_none()&&self.ready.is_none()&&self.packet.is_none()&&self.surface.is_none()&&self.mesh_key.is_none()}
}
fn mesh_receiving_fault(_:Mesh3dFault)->semio_framework_job::OriginalTurnFailure{semio_framework_value::ValueError::literal(semio_framework_value::ValueRefusalKind::InvariantViolated,"original mesh packet failed its exact receiving frontier").into()}
impl Drop for UiNativeMeshReceiving{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original mesh receiving reached Drop before destination and source closure")}}
